93	export function describeIssues(issues: WikilinkIssue[]): string {
94		const lines = issues.map((issue) => {
95			const why =
96				issue.kind === "out-of-docs"
97					? "指向 docs/ 之外——wikilink 仅可引用文档库内的内容"
98					: issue.kind === "absolute"
99						? "使用了绝对路径——wikilink 必须相对 docs/"
100						: "目标文件不存在";
101			return `  • ${issue.raw} — ${why}`;
102		});
103	
104		return [
105			"wikilink-lint：以下 wikilink 不合规，已阻断写入：",
106			...lines,
107			"请先创建缺失文件、改为指向 docs/ 内已存在的文档，或对库外内容（如代码）改用普通文字 / 行内代码描述，然后重试。",
