export function useKeypress(userHandler) {
    const signal = useRef(userHandler);
    signal.current = userHandler;
    useEffect((rl) => {
        let ignore = false;
        const handler = withUpdates((_input, event) => {
            if (ignore)
                return;
            void signal.current(event, rl);
        });
        process.stderr.write('ADD\n'); rl.input.on('keypress', handler);
        return () => {
            ignore = true;
            process.stderr.write('REM\n'); rl.input.removeListener('keypress', handler);
        };
    }, []);
}

